head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vScrenTpCD = "";
scwin.Tpcd = "4";
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용
// var vSecugrpID = SECUGRP_ID_ST; //(주권)메뉴단에서 파라미터로 받자..
scwin.fr_SecuGrpId = $c.lc.fn_getSecuGrpId($c.stf.InfoMenuID());

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */

        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        $c.libRoundPanel.PanelToGroupBox(panel_Sub);
        const sbmOptions = {
            id : "sbm_dts_delistMaster",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_delistMaster=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        dts_delistMaster.insertRow();
        const sbmOptions2 = {
            id : "sbm_dts_delistinsert",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_delistinsert=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        // buttonSet.setInsertInfo( btn_New, fn_New );
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제
        buttonSet.setDsclInfo(btn_Dscl, scwin.dscl); // 안내문작성
        // buttonSet.setMaktInfo( btn_Makt, fn_makt );                // 시장시스템전송

        buttonSet.setInsertStatus();
        buttonSet.setButtonSecugrpDepCd(dts_ByCorpDepCd, scwin.fr_SecuGrpId, txb_IsurCd.getValue(), js_dep_cd);
        label_1.hide();
        txb_ISU_CD.hide();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05411.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    txb_title.setValue("");
    txb_ISU_KOR_NM.setValue("");
    txa_DELIST_ADVNOTI_RSN.Text = "";
    edt_TRST_END_DD.setValue("");
    txa_GRND_REGUL_CONTN.Text = "";
    txa_REMK.Text = "";
    txb_ISU_CD.setValue("");
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        if (txb_IsurCd.getValue() === "") {
            await $c.win.alert("[위탁회사]를 선택하세요.");
            txb_IsurNm.focus();
            return;
        } else {
            scwin.init();
            await scwin.searchList();
            buttonSet.setInsertStatus();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05411.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name img_COM_NM_onclick
 * @description img_COM_NM 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_COM_NM_onclick = async function() {
    try {
        fn_GetPar = scwin.getParStdInd;
        fn_SetPar = scwin.setParStdInd;

        // fn_PopFindCorpChrg(vSecugrpID);
        $c.lc.fn_PopFindCorpChrg(scwin.fr_SecuGrpId);
        await scwin.searchList();
        buttonSet.setInsertStatus();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05411.img_COM_NM_onclick" });
    }
};

/**
 * @method
 * @name dts_list_OnLoadCompleted
 * @description dts_list 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_list_OnLoadCompleted = async function(rowcount) {
    try {
        edt_TotalCnt1.setValue("총 " + dts_list.getRowCount() + "건");
        let isur_cd = txb_IsurCd.getValue();
        await scwin.searchDetaillist(isur_cd);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05411.dts_list_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_detaillist_OnLoadCompleted
 * @description dts_detaillist 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_detaillist_OnLoadCompleted = function(rowcount) {
    try {
        edt_TotalCnt.setValue("총 " + dts_detaillist.getRowCount() + "건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05411.dts_detaillist_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_delisting_OnClick
 * @description grd_delisting 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {*} Row Row
 * @param {*} Colid Colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_delisting_OnClick = function(Row, Colid) {
    try {
        const temp = "";
        const content = "";
        const title = "";
        const count = 0;

        /*for (var i = 1; i <= dts_list.CountRow; i++) {
    		if (dts_list.RowMark(i)  == 1)  {
                if (!temp)  {
                    temp = dts_list.NameString(i, "ISU_KOR_NM");
                }
    		}
        }*/

        // title = temp + " 수익증권 " +(count >= 2 ? "외" + (count - 1 ) + "건" : "") + " 상장폐지 예고안내";

        txb_title.setValue(dts_list.getCellData(Row, "ISU_KOR_NM") + " 수익증권 상장폐지 예고안내");
        txb_ISU_KOR_NM.setValue(dts_list.getCellData(Row, "ISU_KOR_NM"));
        txa_DELIST_ADVNOTI_RSN.Text = "신탁기간만료(" + dts_list.getCellData(Row, "TRST_END_DD").substring(0, 4) + "." + dts_list.getCellData(Row, "TRST_END_DD").substring(4, 6) + "." + dts_list.getCellData(Row, "TRST_END_DD").substring(6, 8) + ")시 상장폐지 예정";
        edt_TRST_END_DD.setValue(dts_list.getCellData(Row, "TRST_END_DD"));
        txa_GRND_REGUL_CONTN.Text = "유가증권시장상장 규정 제109조";
        txa_REMK.Text = "";
        txb_ISU_CD.setValue(dts_list.getCellData(Row, "ISU_CD"));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05411.grd_delisting_OnClick" });
    }
};

/**
         * @method
         * @name grd_Delistdetail_OnClick
         * @description grd_Delistdetail 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
         * @param {Number} row 행 인덱스
         * @param {*} colid colid
         * @returns {Promise<void>}
         * @hidden N
         */
scwin.grd_Delistdetail_OnClick = async function(row, colid) {
    try {
        const bzprocscd = dts_detaillist.getCellData(dts_detaillist.getRowPosition(), "BZ_PROCS_NO");
        await scwin.searchDelistMaster(bzprocscd);
        if (dts_detaillist.getCellData(dts_detaillist.getRowPosition(), "DISCLS_YN") === "Y") {
            buttonSet.setErrorStatus();
        } else {
            buttonSet.setUpdateStatus();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05411.grd_Delistdetail_OnClick" });
    }
};

