///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name searchList
 * @description search List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchList = async function() {
    // dts_IndustryChange.NameValue(1,"BZ_PROCS_NO")= fr_bz_procs_no;
    url += "?SCREN_ID=" + "ULDSTF05411.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=incoSearchlist&inputMessageId=DELISTING_INOUT&outputMessageId=DELISTING_INOUT" + "&ISUR_CD=" + txb_IsurCd.getValue();
    const sbmOptions = {
        id : "sbm_dts_list",
        action : "/Delisting.do",
        ref : "",
        target : "dts_list=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name searchDetaillist
 * @description search Detaillist 처리
 * @param {*} isur_cd isur_cd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchDetaillist = async function(isur_cd) {
    // dts_IndustryChange.NameValue(1,"BZ_PROCS_NO")= fr_bz_procs_no;
    url += "?SCREN_ID=" + "ULDSTF05411.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=incoSearchdetaillist&inputMessageId=DELISTING_INOUT&outputMessageId=DELISTING_INOUT" + "&ISUR_CD=" + isur_cd;
    const sbmOptions = {
        id : "sbm_dts_detaillist",
        action : "/Delisting.do",
        ref : "",
        target : "dts_detaillist=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name searchDelistMaster
 * @description search Delist Master 처리
 * @param {*} bzprocscd bzprocscd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchDelistMaster = async function(bzprocscd) {
    const BZ_PROCS_NO = bzprocscd;
    url += "?SCREN_ID=" + "ULDSTF05411.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=incoSearchMaster&inputMessageId=DELISTING_INOUT&outputMessageId=DELISTING_INOUT&ISUR_CD=" + txb_IsurCd.getValue() + "&BZ_PROCS_NO=" + BZ_PROCS_NO;
    const sbmOptions = {
        id : "sbm_dts_delistMaster",
        action : "/Delisting.do",
        ref : "",
        target : "dts_delistMaster=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @param {*} pProcsNo pProcsNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function(pProcsNo) {
    if (TR_JOB === 'I') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (TR_JOB === 'U') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    }
    dts_delistinsert.removeAll();
    dts_delistinsert.removeAll();
    dts_delistinsert.insertRow();
    dts_delistinsert.setCellData(1, "BZ_PROCS_NO", pProcsNo);
    dts_delistinsert.setCellData(1, "ISU_CD", txb_ISU_CD.getValue());
    trs_update.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_update",
        action : "/Delisting.do",
        ref : "dts_delistMaster,dts_delistinsert",
        target : "trs_update=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name deleteTrs
 * @description delete Trs 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteTrs = async function() {
    trs_delete.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_delete",
        action : "/Delisting.do",
        ref : "dts_delistMaster,dts_delistinsert",
        target : "trs_delete=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

