///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParStdInd
 * @description mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 법인선택팝업에서 fr_SecuGrpId 변수를 참조.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParStdInd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_IsurCd.getValue(); // 코드값을 포함할 컨트롤
    arrPar[1] = txb_IsurNm.getValue(); // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤
    // arrPar[2] = vSecugrpID;                                   // 명칭값을 포함할 컨트롤
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParStdInd
 * @description set Par Std Ind 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParStdInd = function(arrPar) {
    txb_IsurCd.setValue(arrPar[0].ISUR_CD);
    txb_IsurNm.setValue(arrPar[0].COM_NM);
    scwin.init();
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (txb_IsurCd.getValue() === "") {
        await $c.win.alert("[위탁회사]를 선택하세요.");
        txb_IsurNm.focus();
        return false;
    }
    if (txb_title.getValue() === "") {
        await $c.win.alert("[제목]를 입력하세요.");
        txb_title.focus();
        return false;
    } else {
        if (!$c.stf.checkMaxLength(txb_title, 500, "제목")) return false;
    }
    if (txb_ISU_KOR_NM.getValue() === "") {
        await $c.win.alert("[종목명]을 입력하세요.");
        txb_ISU_KOR_NM.focus();
        return false;
    }
    if (txb_ISU_CD.getValue() === "") {
        // 추가
        await $c.win.alert("[종목]을 선택하세요.");
        return false;
    }
    if (txa_DELIST_ADVNOTI_RSN.Text === "") {
        await $c.win.alert("[상장폐지 예고사유]를 입력하세요.");
        txa_DELIST_ADVNOTI_RSN.focus();
        return false;
    }
    if (edt_TRST_END_DD.getValue() === "") {
        await $c.win.alert("[신탁기간 만료일]을 입력하세요.");
        edt_TRST_END_DD.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    TR_JOB = 'I';
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(TR_JOB)) return;
        vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
        // alert("[저장 vBzProcsNo]"+vBzProcsNo);
        if (vBzProcsNo.length !== 14) {
            await $c.win.alert("업무처리번호생성실패");
        } else {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            //
            // ********************************************************************

            /*ORG SRC: dts_delistMaster.UserStatus(1) = TB_JOB_INSERT;*/
            X = TB_JOB_INSERT;
            dts_delistMaster.setCellData(1, "BZ_PROCS_NO", vBzProcsNo);
            dts_delistMaster.setCellData(1, "INFO_CONTN_TP_CD", scwin.Tpcd);
            await scwin.trs(vBzProcsNo);
        }
    }
};

