};

/**
 * @method
 * @name print
 * @description 화면을 인쇄한다.
 * @returns {void}
 * @hidden N
 */
scwin.print = function() {
    const sDepNm_1 = "";
    const sDepNm_2 = "";

    // PDF 리포트 파일명
    const pdf_rptname = "RLDSTF00004";
    let contents = "1.상장폐지 예고대상 수익증권:" + dts_delistMaster.getCellData(dts_delistMaster.getRowPosition(), "ISU_KOR_NM") + "수익증권 상장폐지 예고\n";
    contents += "2.상장폐지 예고사유 : 신탁기간만료(" + dts_delistMaster.getCellData(dts_delistMaster.getRowPosition(), "DELIST_ADVNOTI_RSN") + "\n";
    contents += "3.신탁기간 만료일:" + dts_delistMaster.getCellData(dts_delistMaster.getRowPosition(), "TRST_END_DD").substring(0, 4) + "." + dts_delistMaster.getCellData(dts_delistMaster.getRowPosition(), "TRST_END_DD").substring(4, 6) + "." + dts_delistMaster.getCellData(dts_delistMaster.getRowPosition(), "TRST_END_DD").substring(6, 8) + "\n";
    contents += "4.근거규정 :" + dts_delistMaster.getCellData(dts_delistMaster.getRowPosition(), "GRND_REGUL_CONTN") + "\n";
    contents += "5.기타 투자판단에 참고할 사항 :" + dts_delistMaster.getCellData(dts_delistMaster.getRowPosition(), "REMK") + "\n\n";
    contents = $c.ut.replaceAll(contents, '\n', '<br>');
    contents = $c.ut.replaceAll(contents, ' ', '&nbsp;');
    let userParam = [{
        uid: "DEP_NM_1",
        unm: $c.ut.defaultStrHtmlSpace(sDepNm_1)
    }, {
        uid: "DEP_NM_2",
        unm: $c.ut.defaultStrHtmlSpace(sDepNm_2)
    }, {
        uid: "ISUR_CD",
        unm: $c.ut.defaultStrHtmlSpace(txb_IsurCd.getValue())
    }, {
        uid: "COM_NM",
        unm: $c.ut.defaultStrHtmlSpace(txb_IsurNm.getValue())
    }, {
        uid: "TITLE",
        unm: $c.ut.defaultStrHtmlSpace(txb_title.getValue())
    }, {
        uid: "BODY",
        unm: contents
    }];
    $c.stf.doLogSave("ULDSTF05411.xml", SCREN_PROCS_TP_CD_05);

    // PDF Convert
    $c.rpt.fn_open_report_pdf(pdf_rptname, userParam);
};

